import { prisma } from "../lib/prisma";

function slugCode(name: string, max = 4) {
  return name
    .replace(/[^a-zA-Z0-9 ]/g, "")
    .split(/\s+/)
    .map((w) => w[0] || "")
    .join("")
    .slice(0, max)
    .toUpperCase() + "-" + Date.now().toString().slice(-4);
}

