export async function seedHealthCenters() {
  const regionCache = new Map<string, any>();
  const districtCache = new Map<string, any>();

  const toNumeric = (v: any) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : 0;
  };

  for (const item of healthcenter) {
    const regionName = (item.Region || "").toString().trim();
    const zone = (item.Zone || "").toString().trim();
    const woreda = (item.Woreda || "").toString().trim();
    const hfName = (item.HF_Name || "").toString().trim();

    if (!hfName) continue;

    let region: any | undefined;
    if (regionName) {
      if (regionCache.has(regionName)) {
        region = regionCache.get(regionName);
      } else {
        region = await prisma.region.findUnique({
          where: { name: regionName },
        });
        if (!region) {
          const code = slugCode(regionName, 4);
          region = await prisma.region.create({
            data: { name: regionName, code },
          });
        }
        regionCache.set(regionName, region);
      }
    }

    let district: any | undefined;
    if (woreda && region && region.id) {
      const districtKey = `${region.id}::${woreda}`;
      if (districtCache.has(districtKey)) {
        district = districtCache.get(districtKey);
      } else {
        district = await prisma.district.findFirst({
          where: { regionId: region.id, name: woreda },
        });
        if (!district) {
          const code = slugCode(`${region.code}-${woreda}`, 10);
          district = await (prisma as any).district.upsert({
            where: { code },
            update: {
              name: woreda,
              regionId: region.id,
            },
            create: {
              name: woreda,
              code,
              regionId: region.id,
            },
          });
        }
        districtCache.set(districtKey, district);
      }
    }

    // Find by the unique constraint: [districtId, HF_Name]
    const existing = await (prisma as any).healthFacility.findFirst({
      where: {
        districtId: district?.id,
        HF_Name: hfName,
      },
    });

    const yVal = toNumeric(item.Y);
    const xVal = toNumeric(item.X);
    
    // Validate and constrain coordinates to valid range for Decimal(9,6)
    // Valid range: -999.999999 to 999.999999
    const constrainDecimal = (val: number) => {
      if (!Number.isFinite(val)) return 0;
      if (val > 999.999999) return 999.999999;
      if (val < -999.999999) return -999.999999;
      return val;
    };

    const data: any = {
      regionId: region?.id || null,
      districtId: district?.id || null,
      Region: regionName || "",
      Zone: zone || "",
      Woreda: woreda || "",
      HF_Name: hfName,
      HF_Type: (item.HF_Type || "").toString(),
      Y: constrainDecimal(yVal),
      X: constrainDecimal(xVal),
      X1: toNumeric(item.X1),
      N: toNumeric(item.N),
      E: toNumeric(item.E),
      Z: toNumeric(item.Z),
      owner: item.owner && item.owner !== "" ? item.owner : null,
      Status: item.Status && item.Status !== "" ? item.Status : null,
    };

    if (existing) {
      await (prisma as any).healthFacility.update({ where: { id: existing.id }, data });
    } else {
      await (prisma as any).healthFacility.create({ data });
    }
  }
}

if (require.main === module) {
  seedHealthCenters()
    .then(() => {
      console.log("Seeded health facilities");
      process.exit(0);
    })
    .catch((e) => {
      console.error(e);
      process.exit(1);
    });
}

export default healthcenter;